def main():
    N = int(input())
    intervals = []

    for _ in range(N):
        start, end = map(int, input().split())
        intervals.append((start, end))

    intervals.sort()

    n_intersections = 0

    for i in range(N):
        for j in range(i + 1, N):
            if intervals[i][1] >= intervals[j][0]:
                n_intersections += 1
            else:
                break

    print(n_intersections)
